    root.append(template.content.cloneNode(true));

    this.#trigger = root.querySelector('button');
    this.#heading = root.querySelector('.heading');
    this.#region = root.querySelector('#panel');

    // Pointer activation.
    this.#trigger.addEventListener('click', () => {
      this.open = !this.open;
    });

    // Keyboard activation: Enter or Space toggles, exactly like a native button.
    this.#trigger.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault(); // Space would otherwise scroll the page
        this.open = !this.open;
      }
    });
  }

  connectedCallback() {
    // Sync shadow state with whatever markup provided (attribute may predate upgrade).
    this.#render();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name !== 'open' || oldValue === newValue) return;
    // Attribute changed from outside OR via our own reflection: one code path.
    this.#dispatch(oldValue !== null, newValue !== null);
    this.#render();
  }

  get heading() {
    return this.getAttribute('heading') ?? '';
  }

  set heading(value) {
    this.setAttribute('heading', String(value));
  }

  /** Property mirror of the `open` attribute (reflected both ways). */
  get open() {
    return this.hasAttribute('open');
  }

  set open(value) {
    this.toggleAttribute('open', Boolean(value));
  }

  /** Force-open with `true`, force-closed with `false`, plain toggle otherwise. */
  toggle(force) {
    const next = force === undefined ? !this.open : Boolean(force);
    this.open = next;
    return next;
  }

  #dispatch(fromState, toState) {
    this.dispatchEvent(new CustomEvent('toggle', {
      bubbles: true,
      composed: true,
      detail: {
        oldState: fromState ? 'open' : 'closed',
        newState: toState ? 'open' : 'closed',
      },
    }));
  }

  #render() {
    const open = this.open;
    this.#trigger.setAttribute('aria-expanded', String(open));
    this.#region.hidden = !open;
    this.#heading.textContent = this.heading;
  }
}

if (!customElements.get('collapsible-panel')) {
