result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wc-panel/test/collapsible-panel.test.js", "content": "import { describe, it, expect, beforeEach } from 'vitest';
import './src/collapsible-panel.js';

const define = (html) => {
  const host = document.createElement('div');
  host.innerHTML = html.trim();
  const el = host.firstElementChild;
  document.body.append(host);
  return el;
};

beforeEach(() => {
  document.body.innerHTML = '';
});

describe('<collapsible-panel>', () => {
  it('upgrades and renders its shadow structure', () => {
    const el = define(`<collapsible-panel heading="Details">Body</collapsible-panel>`);
    expect(el.shadowRoot.querySelector('button[part="trigger"]')).toBeTruthy();
    expect(el.shadowRoot.querySelector('.heading').textContent).toBe('Details');
  });

  it('starts closed: aria-expanded=false and region hidden', () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    expect(el.hasAttribute('open')).toBe(false);
    expect(el.open).toBe(false);
    const trigger = el.shadowRoot.querySelector('button');
    const region = el.shadowRoot.querySelector('#panel');
    expect(trigger.getAttribute('aria-expanded')).toBe('false');
    expect(region.hidden).toBe(true);
  });

  // ---- Reflection: attribute -> property / shadow state -----------------

  it('setting the open attribute programmatically opens it', () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    el.setAttribute('open', '');
    expect(el.open).toBe(true);
    expect(el.shadowRoot.querySelector('button').getAttribute('aria-expanded')).toBe('true');
    expect(el.shadowRoot.querySelector('#panel').hidden).toBe(false);
  });

  it('observedAttributes picks up `open` changing after connection, both ways', async () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    await Promise.resolve();
    el.setAttribute('open', '');
    expect(el.open).toBe(true);
    el.removeAttribute('open');
    expect(el.open).toBe(false);
    expect(el.shadowRoot.querySelector('#panel').hidden).toBe(true);
  });

  // ---- Reflection: property/interaction -> attribute --------------------

  it('property setter reflects to the open attribute', () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    el.open = true;
    expect(el.hasAttribute('open')).toBe(true);
    el.toggle();
    expect(el.hasAttribute('open')).toBe(false);
    el.toggle(true);
    expect(el.hasAttribute('open')).toBe(true);
    el.toggle(false);
    expect(el.hasAttribute('open')).toBe(false);
  });

  it('user interaction (click) updates the attribute and aria state', async () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    el.shadowRoot.querySelector('button').click();
    expect(el.hasAttribute('open')).toBe(true);
    expect(el.shadowRoot.querySelector('button').getAttribute('aria-expanded')).toBe('true');
    el.shadowRoot.querySelector('button').click();
    expect(el.hasAttribute('open')).toBe(false);
    expect(el.shadowRoot.querySelector('button').getAttribute('aria-expanded')).toBe('false');
  });

  // ---- aria-expanded truthfulness ---------------------------------------

  it('aria-expanded is always the literal string "true"/"false", matching reality', () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    const trigger = el.shadowRoot.querySelector('button');
    for (const _ of [1, 2, 3]) {
      trigger.click();
      expect(trigger.getAttribute('aria-expanded')).toBe(el.hasAttribute('open') ? 'true' : 'false');
      expect(trigger.getAttribute('aria-expanded') === 'true').toBe(!el.shadowRoot.querySelector('#panel').hidden);
    }
  });

  it('aria-controls points at the content region id', () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    const trigger = el.shadowRoot.querySelector('button');
    expect(trigger.getAttribute('aria-controls')).toBe('panel');
    expect(el.shadowRoot.getElementById('panel')).toBeTruthy();
  });

  it('heading attribute updates are reflected in the trigger label', () => {
    const el = define(`<collapsible-panel heading="Old">x</collapsible-panel>`);
    el.setAttribute('heading', 'New');
    expect(el.shadowRoot.querySelector('.heading').textContent).toBe('New');
  });

  // ---- Keyboard activation ----------------------------------------------

  it('Enter on the focused trigger toggles via dispatched KeyboardEvent', async () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    const trigger = el.shadowRoot.querySelector('button');
    const press = (key) =>
      trigger.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true }));

    press('Enter');
    expect(el.hasAttribute('open')).toBe(true);
    expect(trigger.getAttribute('aria-expanded')).toBe('true');

    press('Enter');
    expect(el.hasAttribute('open')).toBe(false);

    // Other keys do nothing.
    press('ArrowDown');
    expect(el.hasAttribute('open')).toBe(false);
  });

  it('Space on the focused trigger toggles and prevents page scroll', async () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    const trigger = el.shadowRoot.querySelector('button');
    const event = new KeyboardEvent('keydown', { key: ' ', bubbles: true, cancelable: true });
    trigger.dispatchEvent(event);
    expect(event.defaultPrevented).toBe(true);
    expect(el.hasAttribute('open')).toBe(true);
    trigger.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', cancelable: true }));
    expect(el.hasAttribute('open')).toBe(false);
  });

  // ---- toggle events ------------------------------------------------------

  it('dispatches a toggle event with oldState/newState detail', async () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    const events = [];
    el.addEventListener('toggle', (e) => events.push({ ...e.detail }));

    el.setAttribute('open', '');
    el.removeAttribute('open');
    el.shadowRoot.querySelector('button').click(); // opens
    el.open = false;                               // closes

    expect(events.map((e) => `${e.oldState}->${e.newState}`)).toEqual([
      'closed->open',
      'open->closed',
      'closed->open',
      'open->closed',
    ]);
  });

  it('toggle event bubbles and crosses the shadow boundary', async () => {
    const el = define(`<collapsible-panel heading="T">x</collapsible-panel>`);
    let seen = false;
    document.body.addEventListener('toggle', () => (seen = true), { once: true });
    el.open = true;
    expect(seen).toBe(true);
  });

  it('does not dispatch when setting an already-current value', () => {
    const el = define(`<collapsible-panel heading="T" open>x</collapsible-panel>`);
    const events = [];
    el.addEventListener('toggle', (e) => events.push(e));
    el.setAttribute('open', ''); // no-op change ('' === '')
    el.open = true;              // no-op reflection
    expect(events).toHaveLength(0);
  });

  // ---- Light DOM / slotting ------------------------------------------------

  it('keeps slotted content in light DOM and conveys visibility via hidden on the region', async () => {
    const child = document.createElement('p');
    child.textContent = 'light dom content';
    const el = define(`<collapsible-panel heading="T"></collapsible-panel>`);
    el.append(child);

    const region = el.shadowRoot.querySelector('#panel');
    expect(child.parentNode).toBe(el); // still light DOM
    expect(child.isConnected).toBe(true);

    el.setAttribute('open', '');
    expect(region.hidden).toBe(false);
    expect(child.offsetParent).not.toBeNull?.() ?? true;

    el.removeAttribute('open');
    expect(region.hidden).toBe(true); // hidden attribute hides region + slotted content

    // Slotted content is distributed into the region.
    const assigned = region.querySelector('slot').assignedNodes();
    expect(assigned).toContain(child);
  });
});
"})
